<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import ReferenceIcon from '@/ui/ReferenceIcon.vue'
import {WarningFilled} from '@element-plus/icons-vue'
import type {ApiError} from '@/core/http'
import RuleGatewayFunctionPreview from './RuleGatewayFunctionPreview.vue'
import RuleFunctionCodeEditor from './RuleFunctionCodeEditor.vue'
import RuleExternalActionDialog from './RuleExternalActionDialog.vue'
import RuleOtaCheckDialog from './RuleOtaCheckDialog.vue'
import {sourceSelectionInput,type RuleSourceInput} from './rule-source-selection'
import {deviceSourceMembers,sourceContract,type RuleDeviceSourceContract} from './rule-source-api'
import {externalAction} from './rule-external-action-draft'
import {projectId} from '@/core/session'
import RuleActionDeviceTarget,{type RuleActionDeviceTarget as DeviceTarget} from './RuleActionDeviceTarget.vue'
import type {Schema} from '@/core/contracts'
import {ExactDecimal,parsePreprocessJson,writePreprocessJson,type ExactJson} from './preprocess-exact-json'
import RuleActionValueEditor from './RuleActionValueEditor.vue'
export type ActionCommand={token:string;kind:'ADD'}|{token:string;kind:'EDIT'|'REMOVE';id:string}
export type ActionDraft={id:string;nodeType:string;config:Record<string,ExactJson>;credential?:{mode:'REPLACE';writeId:string;value:string}|{mode:'CLEAR'}}
const props=defineProps<{modelValue:ActionDraft[];catalog:Schema<'Catalog'>;disabled?:boolean;readOnly?:boolean;presentation?:'table'|'cards';sorting?:boolean;deviceSource?:RuleSourceInput|RuleDeviceSourceContract;triggerKind?:NonNullable<Schema<'MessageRuleContentTrigger'>['kind']>;detail?:boolean;command?:ActionCommand;requestError?:string}>()
const emit=defineEmits<{'update:modelValue':[value:ActionDraft[]];locked:[value:boolean];'authority-denied':[cause:ApiError];command:[value:Omit<Extract<ActionCommand,{kind:'EDIT'|'REMOVE'}>,'token'>|{kind:'ADD'}];commit:[];cancelCommand:[]}>()
const functionDialog=ref(false),functionNode=ref(''),functionId=ref(''),functionSource=ref(''),functionProtocol=ref(''),functionStream=ref(''),delayEnabled=ref(false),delaySeconds=ref(1),functionError=ref('')
const functionTarget=ref<DeviceTarget>(),targetSeed=ref<string>(),targetBusy=ref(false),targetTurn=ref(0)
const genericDialog=ref(false),genericDraft=ref<ActionDraft>(),draggedId=ref(''),dropId=ref('')
const previewBusy=ref(false),sourceEditing=ref(false),externalDraft=ref<ActionDraft>(),otaDraft=ref<ActionDraft>(),actionError=ref('')
const removing=ref<ActionDraft>()
const picker=ref(false),editors=ref<{valid:()=>boolean}[]>([])
defineExpose({valid:()=>!functionDialog.value&&!genericDialog.value&&!externalDraft.value&&!otaDraft.value})
const cardView=computed(()=>props.readOnly||props.presentation==='cards')
const canSort=computed(()=>props.sorting&&!props.disabled)
const labels:Record<string,string>={'event-ota-check-action':'OTA 升级检查','external-url-forward-action':'推送到外部 URL','external-mqtt-forward-action':'推送到外部 MQTT','event-device-properties-function':'向其它设备下发属性','event-device-command-function':'向其它设备下发命令','report-cloud-function':'自定义云函数','report-gateway-properties-function':'向当前网关上报子设备属性','device-report-properties-function':'向指定设备下发属性','device-report-cloud-properties-function':'向指定设备更新云端属性','device-report-command-function':'向指定设备下发命令','device-report-data-function':'向指定设备下发自定义数据','current-device-properties-function':'向当前设备下发属性','current-device-command-function':'向当前设备下发命令','current-device-data-function':'自定义数据下发函数','event-cloud-function':'云函数','current-device-cloud-properties-function':'向当前设备更新云端属性','current-device-report-data-function':'向当前设备下发自定义数据','device-property-set-action':'向当前设备下发属性','device-command-action':'向当前设备下发命令','webhook-action':'推送到外部 URL','email-action':'发送邮件通知','notification-action':'发送通知','device-notification-action':'设备消息通知','alarm-create-action':'创建告警','alarm-clear-action':'清除告警'}
const fieldLabels:Record<string,string>={properties:'属性',commandKey:'命令标识符',input:'命令参数',url:'URL',body:'内容',recipient:'接收人',subject:'主题',channel:'通知渠道',deviceIds:'通知设备',notification:'通知内容',alarmRuleId:'告警规则'}
const catalogActions=computed(()=>props.catalog.actions??[])
// 只收窄已确定类型来源的新增菜单；历史操作的配置仍从完整目录读取。
const options=computed(()=>{
 if(previewDeviceSource.value?.kind!=='DEVICE_TYPE')return catalogActions.value
 const excluded=props.triggerKind==='ATTRS_RPT'?['device-report-properties-function','device-report-cloud-properties-function','device-report-command-function','device-report-data-function']:props.triggerKind==='EVENT_RPT'?['event-device-properties-function','event-device-command-function']:[]
 return catalogActions.value.filter(item=>!excluded.includes(item.nodeType??''))
})
function actionDescription(type:string){if(type==='event-ota-check-action')return '通过设备事件来实现设备 OTA 升级检查，自动关联 OTA 版本库，将需要升级的固件信息下发给设备。';if(type==='event-cloud-function'&&props.triggerKind==='EVENT_RPT')return '可以自定义编写基于 Javascript 的云函数，调用内置函数库实现各类操作。';const name=props.triggerKind==='ATTRS_RPT'?'属性':'事件';return type==='external-mqtt-forward-action'?`将设备上报的${name}消息转发到外部的 MQTT Broker，实现更多基于实时数据的应用。`:type==='external-url-forward-action'?`将设备上报的${name}消息转发到外部的 URL，方便 Web 应用获取设备实时数据。`:descriptions[type]}
function display(value:ExactJson):string{return typeof value==='string'?value:writePreprocessJson(value)}
function schema(type:string){const raw=catalogActions.value.find(item=>item.nodeType===type)?.configSchema;return raw&&typeof raw==='object'&&!Array.isArray(raw)?raw as {properties?:Record<string,{type?:string;enum?:string[]}>;required?:string[]}:undefined}
function add(type:string){if(props.disabled||props.readOnly||props.modelValue.length>=32)return;if(type==='event-ota-check-action'){openOta({id:crypto.randomUUID(),nodeType:type,config:{versionProperty:'',module:'main'}});return}if(externalAction(type)){openExternal({id:crypto.randomUUID(),nodeType:type,config:type==='external-url-forward-action'?{url:'',messageFormat:'SIMPLE',ignoreSslError:false}:{host:'',port:new ExactDecimal('8883'),topic:'',messageFormat:'SIMPLE',tls:true}});return}if(isFunctionType(type)){openFunction(type);return}const fields=schema(type);if(!fields)return;const config:Record<string,ExactJson>=Object.create(null);for(const name of fields.required??[]){const field=fields.properties?.[name];config[name]=field?.enum?.[0]??(field?.type==='object'?Object.create(null):field?.type==='array'?[]:field?.type==='number'?new ExactDecimal('0'):'')}openGeneric({id:crypto.randomUUID(),nodeType:type,config});picker.value=false}
function openGeneric(row:ActionDraft){if(props.disabled||props.readOnly)return;genericDraft.value={...row,config:parsePreprocessJson(writePreprocessJson(row.config)) as ActionDraft['config']};genericDialog.value=true}
function editAction(row:ActionDraft){if(row.nodeType==='event-ota-check-action'){openOta(row);return}if(externalAction(row.nodeType)){openExternal(row);return}if(isFunction(row))openFunction(row.nodeType,row);else openGeneric(row)}
function openOta(row:ActionDraft){if(props.disabled||props.readOnly)return;if(!props.deviceSource){actionError.value='请选择设备来源后配置OTA检查';return}actionError.value='';otaDraft.value={...row,config:{...row.config}};picker.value=false}
function saveOta(row:ActionDraft){if(props.disabled||props.readOnly||!otaDraft.value||row.id!==otaDraft.value.id||row.nodeType!==otaDraft.value.nodeType)return;const exists=props.modelValue.some(old=>old.id===row.id);if(!exists&&props.modelValue.length>=32)return;emit('update:modelValue',exists?props.modelValue.map(old=>old.id===row.id?row:old):[...props.modelValue,row]);if(props.detail)emit('commit');else otaDraft.value=undefined}
function openExternal(row:ActionDraft){if(props.disabled||props.readOnly)return;externalDraft.value={...row,config:parsePreprocessJson(writePreprocessJson(row.config)) as ActionDraft['config']};picker.value=false}
function saveExternal(row:ActionDraft){if(props.disabled||props.readOnly||!externalDraft.value||row.id!==externalDraft.value.id||row.nodeType!==externalDraft.value.nodeType)return;const exists=props.modelValue.some(old=>old.id===row.id);if(!exists&&props.modelValue.length>=32)return;emit('update:modelValue',exists?props.modelValue.map(old=>old.id===row.id?row:old):[...props.modelValue,row]);if(props.detail)emit('commit');else externalDraft.value=undefined}
function saveGeneric(){const row=genericDraft.value;if(props.disabled||!row||!editors.value.every(editor=>editor.valid()))return;const exists=props.modelValue.some(old=>old.id===row.id);if(!exists&&props.modelValue.length>=32)return;emit('update:modelValue',exists?props.modelValue.map(old=>old.id===row.id?row:old):[...props.modelValue,row]);if(props.detail)emit('commit');else{genericDialog.value=false;genericDraft.value=undefined}}
function updateGeneric(name:string,value:ExactJson){if(!props.disabled&&genericDraft.value)genericDraft.value={...genericDraft.value,config:Object.assign(Object.create(null),genericDraft.value.config,{[name]:value})}}
function requestEdit(row:ActionDraft){if(props.disabled||props.readOnly)return;if(props.detail)emit('command',{kind:'EDIT',id:row.id});else editAction(row)}
function remove(row:ActionDraft){if(props.disabled||props.readOnly)return;if(props.detail)emit('command',{kind:'REMOVE',id:row.id});else emit('update:modelValue',props.modelValue.filter(old=>old.id!==row.id))}
function clearLocal(){picker.value=false;functionDialog.value=false;genericDialog.value=false;genericDraft.value=undefined;externalDraft.value=undefined;otaDraft.value=undefined;removing.value=undefined;functionSource.value='';functionTarget.value=undefined;targetSeed.value=undefined;functionError.value='';actionError.value='';clearDrag()}
function cancelCommand(){if(props.disabled)return;clearLocal();if(props.detail)emit('cancelCommand')}
function confirmRemoval(){if(props.disabled||!removing.value)return;if(props.modelValue.length<=1){actionError.value='请至少保留1项操作，当前操作尚未移除。';return}emit('update:modelValue',props.modelValue.filter(row=>row.id!==removing.value!.id));emit('commit')}
watch(()=>props.command,value=>{if(!props.detail)return;if(!value){clearLocal();return}if(props.disabled||props.readOnly)return;if(value.kind==='ADD')picker.value=true;else{const row=props.modelValue.find(row=>row.id===value.id);if(row){if(value.kind==='EDIT')editAction(row);else removing.value=row}}},{flush:'post'})
function clearDrag(){draggedId.value='';dropId.value=''}
function startDrag(row:ActionDraft,event:DragEvent){if(!canSort.value){event.preventDefault();return}draggedId.value=row.id;if(event.dataTransfer){event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',row.id)}}
function dragOver(row:ActionDraft,event:DragEvent){if(!canSort.value||!draggedId.value||row.id===draggedId.value)return;event.preventDefault();dropId.value=row.id;if(event.dataTransfer)event.dataTransfer.dropEffect='move'}
function drop(row:ActionDraft,event:DragEvent){if(!canSort.value||!draggedId.value)return;event.preventDefault();const from=props.modelValue.findIndex(value=>value.id===draggedId.value),to=props.modelValue.findIndex(value=>value.id===row.id);if(from>=0&&to>=0&&from!==to){const rows=[...props.modelValue],item=rows.splice(from,1)[0]!;rows.splice(to,0,item);emit('update:modelValue',rows)}clearDrag()}
function sortKey(index:number,event:KeyboardEvent){if(!canSort.value||!['ArrowUp','ArrowDown'].includes(event.key))return;event.preventDefault();move(index,event.key==='ArrowUp'?-1:1)}
watch([()=>props.sorting,()=>props.disabled],clearDrag)
function fields(row:ActionDraft){return [...new Set([...Object.keys(schema(row.nodeType)?.properties??{}),...Object.keys(row.config)])]}

const previewDeviceSource=computed<Schema<'MessageRuleContentSource'>|undefined>(()=>{const value=props.deviceSource;if(!value)return undefined;try{const source='members' in value||'name' in value?sourceContract(sourceSelectionInput(value)):value;if(source.kind!=='DEVICE'&&source.kind!=='DEVICE_TYPE')return undefined;deviceSourceMembers(source);return {...source,kind:source.kind}}catch{return undefined}})
const eventTargetTypes=new Set(['event-device-properties-function','event-device-command-function'])
const reportedPreviewTypes=new Set(['current-device-properties-function','current-device-cloud-properties-function','current-device-command-function','current-device-report-data-function','device-report-properties-function','device-report-cloud-properties-function','device-report-command-function','device-report-data-function'])
function canPreviewFunction(type:string):type is NonNullable<InstanceType<typeof RuleGatewayFunctionPreview>['$props']['nodeType']>{return type==='report-gateway-properties-function'||type==='event-device-properties-function'||type==='event-device-command-function'||type==='current-device-data-function'||reportedPreviewTypes.has(type)}
const specifiedTypes=new Set(['event-device-properties-function','event-device-command-function','device-report-properties-function','device-report-cloud-properties-function','device-report-command-function','device-report-data-function'])
const specified=(type:string)=>specifiedTypes.has(type)
const functionOnlyTypes=new Set(['event-cloud-function','report-cloud-function','report-gateway-properties-function'])
const isFunctionType=(type:string)=>specified(type)||functionOnlyTypes.has(type)||type.startsWith('current-device-')&&type.endsWith('-function')
const isFunction=(row:ActionDraft)=>isFunctionType(row.nodeType)
const allowsDelay=(type:string)=>type!=='current-device-data-function'&&!functionOnlyTypes.has(type)&&!eventTargetTypes.has(type)
const dataFunction=(type:string)=>type==='current-device-data-function'||type==='current-device-report-data-function'||type==='device-report-data-function'
const functionGlyph=(type:string)=>externalAction(type)?'󰤲':specified(type)?'󰿨':type==='current-device-data-function'||functionOnlyTypes.has(type)?'󰡱':'󰭽'
const functionIconClass=(type:string)=>type==='report-gateway-properties-function'?'is-report-gateway':type==='report-cloud-function'?'is-report-cloud':''
const descriptions:Record<string,string>={'event-device-properties-function':'可以向项目中的其它设备下发属性值，实现便捷的设备联动控制。','event-device-command-function':'可以向项目中的其它设备下发命令，实现便捷的设备联动控制。','report-cloud-function':'编写基于 Javascript 的云函数，调用内置函数库实现各类操作。','report-gateway-properties-function':'将属性上报转换为网关子设备属性上报。','device-report-properties-function':'向项目中的指定设备下发属性值，实现便捷的设备联动控制。','device-report-cloud-properties-function':'向项目中的指定设备更新云端属性值，不下发到设备。','device-report-command-function':'向项目中的指定设备下发命令，实现便捷的设备联动控制。','device-report-data-function':'向项目中的指定设备下发自定义数据，使用自定义数据流，支持二进制、文本、JSON 等格式。','event-cloud-function':'编写基于 Javascript 的云函数，调用内置函数库实现各类操作。','current-device-properties-function':'实现属性上报触发云平台向当前设备下发属性，属性内容可通过云函数动态构造。','current-device-command-function':'实现属性上报触发云平台向当前设备下发命令，命令内容可通过云函数动态构造。','current-device-data-function':'执行自定义数据下发，可将属性值转换为自定义数据流支持的更多格式。','current-device-cloud-properties-function':'向当前设备更新云端属性，不下发到设备。','current-device-report-data-function':'实现属性上报触发自定义数据下发，数据内容可通过云函数动态构造，支持二进制、文本、JSON 等格式。'}
watch([picker,functionDialog,genericDialog,externalDraft,otaDraft,removing],()=>emit('locked',picker.value||functionDialog.value||genericDialog.value||!!externalDraft.value||!!otaDraft.value||!!removing.value),{flush:'sync'})
function openFunction(type:string,row?:ActionDraft){if(props.disabled||props.readOnly)return;functionNode.value=type;functionId.value=row?.id??'';functionTarget.value=undefined;targetBusy.value=false;targetSeed.value=typeof row?.config.targetDeviceId==='string'?row.config.targetDeviceId:undefined;targetTurn.value++;const value=row?.config.function as Record<string,ExactJson>|undefined;functionSource.value=typeof value?.source==='string'?value.source:type==='event-device-properties-function'?"module.exports = function (event) {\n  var push_attributes = {};\n  return push_attributes;\n}":type==='event-device-command-function'?"module.exports = function (event) {\n  var command = {\n    method: 'command_identifier',\n    params: { x: 1, y: 1 }\n  };\n  return command;\n}":type==='report-cloud-function'?"module.exports = function (report_attributes) {\n  /**\n   * report_attributes:  上报的属性对象，作为函数参数传入\n   */\n  return;\n}":type==='report-gateway-properties-function'?"module.exports = function (report_attributes) {\n  /**\n   * report_attributes:  上报的属性对象，作为函数参数传入\n   */\n\n  var data = {};\n\n  return data;\n}":type==='event-cloud-function'?"module.exports = function (event) {\n  return;\n};":type==='current-device-cloud-properties-function'||type==='device-report-cloud-properties-function'?"module.exports = function(report_attributes) {\n  var update_attributes = {};\n  return update_attributes;\n};":type==='current-device-report-data-function'||type==='device-report-data-function'?"module.exports = function(report_attributes) {\n  return { type: 'text', msg: 'ON' };\n};":type==='current-device-command-function'||type==='device-report-command-function'?"module.exports = function(report_attributes) {\n  return { method: 'command_identifier', params: { x: 1, y: 1 } };\n};":type==='current-device-data-function'?"module.exports = function(push_attributes) {\n  return { type: 'text', msg: 'ON' };\n};":type==='device-report-properties-function'?"module.exports = function(report_attributes) {\n  var push_attributes = {};\n  return push_attributes;\n};":"module.exports = function(report_attributes) {\n  return { property_identifier: 1 };\n};";functionProtocol.value=typeof row?.config.protocol==='string'?row.config.protocol:'';functionStream.value=typeof row?.config.streamIdentifier==='string'?row.config.streamIdentifier:'';delayEnabled.value=row?.config.delaySeconds instanceof ExactDecimal;delaySeconds.value=delayEnabled.value?Number((row!.config.delaySeconds as ExactDecimal).literal):1;functionError.value='';functionDialog.value=true;picker.value=false}
function saveFunction(){if(props.disabled||targetBusy.value||previewBusy.value||sourceEditing.value||!functionDialog.value||!functionId.value&&props.modelValue.length>=32)return;try{if(!functionSource.value.trim()||new TextEncoder().encode(functionSource.value).length>65536)throw new Error('请填写云函数（最多65536字节）');const config:Record<string,ExactJson>={function:{format:'COMMON_JS',source:functionSource.value}};if(specified(functionNode.value)){if(!functionTarget.value||functionTarget.value.projectId!==projectId.value)throw new Error('请选择并核对目标设备');config.targetDeviceId=functionTarget.value.id;}if(dataFunction(functionNode.value)){if(!['MQTT','TCP'].includes(functionProtocol.value)||!/^[A-Za-z0-9_-]{1,64}$/.test(functionStream.value))throw new Error('请选择推送方式并填写自定义数据流标识符');config.protocol=functionProtocol.value;config.streamIdentifier=functionStream.value}if(allowsDelay(functionNode.value)&&delayEnabled.value){if(!Number.isInteger(delaySeconds.value)||delaySeconds.value<1||delaySeconds.value>3600)throw new Error('延迟时间范围：1~3600秒');config.delaySeconds=new ExactDecimal(String(delaySeconds.value))}const row={id:functionId.value||crypto.randomUUID(),nodeType:functionNode.value,config};emit('update:modelValue',functionId.value?props.modelValue.map(old=>old.id===functionId.value?row:old):[...props.modelValue,row]);if(props.detail)emit('commit');else functionDialog.value=false}catch(cause){functionError.value=cause instanceof Error?cause.message:'请补全操作配置'}}
function move(index:number,by:number){if(!canSort.value||index+by<0||index+by>=props.modelValue.length)return;const rows=[...props.modelValue];[rows[index],rows[index+by]]=[rows[index+by]!,rows[index]!];emit('update:modelValue',rows)}
</script>
<template><section class="rule-actions-editor"><el-alert v-if="actionError" :title="actionError" type="warning" :closable="false"/>
 <div v-if="cardView" class="rule-actions"><article v-for="(row,index) in modelValue" :key="row.id" class="operation-card" :class="{'drag-over':dropId===row.id,'dragging':draggedId===row.id}" :data-action-id="row.id" @dragover="dragOver(row,$event)" @dragleave="dropId===row.id&&(dropId='')" @drop="drop(row,$event)">
 <span class="action-icon" :class="[functionIconClass(row.nodeType),{'is-external':externalAction(row.nodeType)}]"><ReferenceIcon :glyph="functionGlyph(row.nodeType)"/></span><div class="action-name">{{labels[row.nodeType]??row.nodeType}}</div>
 <div class="action-ops"><el-button v-if="sorting" class="sort-handle" size="small" :disabled="disabled" :draggable="canSort" :aria-label="'拖拽排序操作 '+(index+1)" title="拖拽排序，或按上下方向键调整" @dragstart="startDrag(row,$event)" @dragend="clearDrag" @keydown="sortKey(index,$event)"><ReferenceIcon glyph="󰒺"/></el-button><template v-if="!readOnly&&!sorting"><el-button size="small" :disabled="disabled" :aria-label="detail?'编辑操作 '+(index+1):'编辑操作'" @click="requestEdit(row)"><ReferenceIcon glyph="󰏫"/></el-button><el-button size="small" type="danger" :disabled="disabled" :aria-label="detail?'移除操作 '+(index+1):'移除操作'" @click="remove(row)"><ReferenceIcon glyph="󰆴"/></el-button></template></div>
 </article><div v-if="!modelValue.length" class="action-empty">暂无数据</div></div>
 <el-table v-else :data="modelValue" :show-header="false" empty-text="暂无数据" class="action-table"><el-table-column><template #default="{row}">{{labels[row.nodeType]??row.nodeType}}</template></el-table-column><el-table-column width="50"><template #default="{row}"><el-button circle size="small" :disabled="disabled" aria-label="编辑操作" @click="requestEdit(row)"><ReferenceIcon glyph="󰏫"/></el-button></template></el-table-column><el-table-column width="50"><template #default="{row}"><el-button circle size="small" type="danger" :disabled="disabled" aria-label="移除操作" @click="remove(row)"><ReferenceIcon glyph="󰆴"/></el-button></template></el-table-column></el-table>
 <el-button v-if="!detail&&!readOnly&&!sorting" class="add-action" type="primary" :disabled="disabled||modelValue.length>=32" @click="picker=true">添加操作</el-button>
 <el-dialog v-model="genericDialog" title="配置操作" width="min(1000px,94vw)" :top="detail?'10vh':undefined" :lock-scroll="!detail" append-to-body :close-on-click-modal="false" :close-on-press-escape="!disabled" :show-close="!disabled" :before-close="cancelCommand"><el-alert v-if="requestError" :title="requestError" type="warning" :closable="false"/><el-form v-if="genericDraft" label-position="top"><el-form-item v-for="name in fields(genericDraft)" :key="name" :label="fieldLabels[name]??name" :required="schema(genericDraft.nodeType)?.required?.includes(name)"><el-select v-if="schema(genericDraft.nodeType)?.properties?.[name]?.enum" :model-value="genericDraft.config[name]??''" :disabled="disabled" @update:model-value="updateGeneric(name,$event)"><el-option v-for="value in schema(genericDraft.nodeType)?.properties?.[name]?.enum" :key="value" :value="value" :label="value"/></el-select><RuleActionValueEditor v-else ref="editors" :model-value="genericDraft.config[name]??''" :disabled="disabled" @update:model-value="updateGeneric(name,$event)"/></el-form-item></el-form><template #footer><el-form :disabled="false"><el-button :disabled="disabled" @click="cancelCommand">取消</el-button><el-button type="primary" :disabled="disabled" @click="saveGeneric">保存</el-button></el-form></template></el-dialog>
